using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // [EF9 Breaking Change] HasIndex throws on Cosmos entities — removed.
        // Cosmos DB indexing is managed via the container's indexing policy.

        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // [EF9 Breaking Change] Default discriminator property renamed from
            // "Discriminator" to "$type". Existing 500K documents use "Discriminator",
            // and direct SQL queries reference c.Discriminator — preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // [EF9 Breaking Change] id values no longer include the discriminator
            // prefix. Existing documents have ids like "Product|123" — keep that format
            // so point-reads and FindAsync continue to work against existing data.
            entity.HasRootDiscriminatorInJsonId(true);
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

